using System.Text.RegularExpressions;

namespace AMORA.Orbit.Services.Implementations;

public static class ClipboardPrivacyFilter
{
    public const int MaxTextLength = 20_000;
    // The two DWORD opt-out formats are intentionally handled conservatively by presence:
    // no delayed-rendered clipboard data needs to be fetched to decide whether to read text.
    public static IReadOnlyList<string> ExcludedFormats { get; } = Array.AsReadOnly(new[]
    {
        "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType", "org.nspasteboard.AutoGeneratedType",
        "ExcludeClipboardContentFromMonitorProcessing", "CanIncludeInClipboardHistory", "CanUploadToCloudClipboard",
        "Clipboard Viewer Ignore", "AMORA.PrivateClipboardRestore"
    });

    public static bool HasExcludedFormat(IEnumerable<string> formats) =>
        formats.Any(format => ExcludedFormats.Contains(format, StringComparer.OrdinalIgnoreCase));

    // Structured secrets are rejected; merely discussing password managers/marker names is allowed.
    private static readonly Regex StructuredSecret = new(
        @"-----BEGIN (?:[A-Z ]+ )?PRIVATE KEY-----|\bBearer\s+[A-Za-z0-9._~+/=-]{12,}|\b(?:sk-[A-Za-z0-9_-]{20,}|AIza[A-Za-z0-9_-]{25,}|gh[pousr]_[A-Za-z0-9]{20,})\b|\beyJ[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}\b|\b(?:password|passwd|api[_ -]?key|access[_ -]?token|client[_ -]?secret)\s*[:=]\s*[""']?[^\s""']{6,}",
        RegexOptions.IgnoreCase | RegexOptions.CultureInvariant, TimeSpan.FromMilliseconds(100));

    public static bool IsSafeText(string? text)
    {
        if (string.IsNullOrWhiteSpace(text) || text.Length > MaxTextLength) return false;
        if (text.Any(c => char.IsControl(c) && c is not '\r' and not '\n' and not '\t')) return false;
        try { return !StructuredSecret.IsMatch(text); }
        catch (RegexMatchTimeoutException) { return false; }
    }
}
